from typing import Iterable

def parse_amount(amount_str: str) -> Decimal:
    """Parse a decimal string into a Decimal, raising ValueError if unparseable."""
    try:
        return Decimal(amount_str)
    except InvalidOperation as e:
        raise ValueError(f"Cannot parse '{amount_str}' as a decimal amount") from e

def format_amount(d: Decimal) -> str:
    """Return a string of d quantized to exactly 2 decimal places (e.g. '12.50')."""
    return str(d.quantize(Decimal("0.01")))

def sum_amounts(amounts: Iterable[Decimal]) -> Decimal:
    """Sum all Decimals in the iterable, returning Decimal(0) for an empty input."""
    total = Decimal(0)
    for a in amounts:
        total += a
    return total
